{
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": [{
              "@type": "Question",
              "name": "Is Luxe Sateen good for hot sleepers?",
              "acceptedAnswer": {
                "@type": "Answer",
                "text": "Luxe Sateen has a smoother, cozier feel than percale, and its long-staple cotton is breathable enough for year-round use. If you sleep very hot and want the crispest, airiest feel, Classic Percale or Washed European Linen is the best fit."
              }
            },{
              "@type": "Question",
              "name": "What's the difference between Classic Percale and Washed Percale?",
              "acceptedAnswer": {
                "@type": "Answer",
                "text": "Same breathable one-over-one-under weave. Washed Percale is garment-washed, so it\u0026#39;s soft from the first night instead of crisp."
              }
            },{
              "@type": "Question",
              "name": "What are the softest Brooklinen sheets?",
              "acceptedAnswer": {
                "@type": "Answer",
                "text": "Luxe Sateen is buttery soft from the first night, with a silky, hotel-smooth finish. Classic Percale and Washed European Linen start crisper and get softer with every wash."
              }
            },{
              "@type": "Question",
              "name": "How deep are your fitted sheets?",
              "acceptedAnswer": {
                "@type": "Answer",
                "text": "Our fitted sheets fit mattresses 10 to 16 inches deep, including most direct-to-consumer and adjustable mattresses."
              }
            },{
              "@type": "Question",
              "name": "How do I dry my sheets? ",
              "acceptedAnswer": {
                "@type": "Answer",
                "text": "Tumble dry on low heat and remove promptly. For Washed European Linen, remove while still slightly damp and lay flat to finish drying."
              }
            }]
    }

